    48	                + reservation.checkIn() + "," + reservation.checkOut() + "," + reservation.guests() + ","
    49	                + reservation.price().nights() + "," + taxOf(reservation).toPlainString()).toList();
    50	    }
    51	
    52	    @Override
    53	    protected String total(List<Reservation> selected) {
    54	        return selected.stream().map(TourismTaxReport::taxOf)
    55	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    56	    }
    57	}

