     1	package hotel.web;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.databind.json.JsonMapper;
     6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     7	import hotel.messages.SentMessages;
     8	import hotel.reports.OccupancyReport;
     9	import hotel.reports.RatePlanReport;
    10	import hotel.reports.RevenueReport;
    11	import hotel.reports.TourismTaxReport;
    12	import hotel.reservations.ErrorCode;
    13	import hotel.reservations.Guest;
    14	import hotel.reservations.HotelException;
    15	import hotel.reservations.NewReservation;
    16	import hotel.reservations.ReservationService;
    17	import hotel.rooms.Rooms;
    18	import io.javalin.Javalin;
    19	import io.javalin.http.Context;
    20	import io.javalin.json.JavalinJackson;
    21	import java.time.LocalDate;
    22	import java.time.YearMonth;
    23	import java.time.format.DateTimeParseException;
    24	
    25	/** The HTTP API the inn's website and front desk call. */
    26	public final class HttpApi {
    27	
    28	    private final Javalin server;
    29	    private final Rooms rooms;
    30	    private final ReservationService reservations;
    31	    private final SentMessages sentMessages;
    32	    private final OccupancyReport occupancyReport;
    33	    private final RevenueReport revenueReport;
    34	    private final TourismTaxReport tourismTaxReport;
    35	    private final RatePlanReport ratePlanReport;
    36	
    37	    public HttpApi(
    38	            Rooms rooms,
    39	            ReservationService reservations,
    40	            SentMessages sentMessages,
    41	            OccupancyReport occupancyReport,
    42	            RevenueReport revenueReport,
    43	            TourismTaxReport tourismTaxReport,
    44	            RatePlanReport ratePlanReport) {
    45	        this.rooms = rooms;
    46	        this.reservations = reservations;
    47	        this.sentMessages = sentMessages;
    48	        this.occupancyReport = occupancyReport;
    49	        this.revenueReport = revenueReport;
    50	        this.tourismTaxReport = tourismTaxReport;
    51	        this.ratePlanReport = ratePlanReport;
    52	
    53	        ObjectMapper jsonMapper = JsonMapper.builder()
    54	                .addModule(new JavaTimeModule())
    55	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    56	                .build();
    57	        this.server = Javalin.create(config -> {
    58	            config.showJavalinBanner = false;
    59	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    60	        });
    61	        registerRoutes();
    62	        registerErrorHandling();
    63	    }
    64	
    65	    public Javalin server() {
    66	        return server;
    67	    }
    68	
    69	    private void registerRoutes() {
    70	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    71	
    72	        server.post("/reservations", ctx -> {
    73	            NewReservation request = readNewReservation(ctx);
    74	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    75	        });
    76	        server.get("/reservations/{id}", ctx ->
    77	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
